    indicacoes = pgTable("indicacoes", {
      id: serial("id").primaryKey(),
      indicouId: integer("indicou_id").references(() => users.id),
      // Quem indicou (pode ser NULL para links de marketing sem beneficiário)
      indicadoId: integer("indicado_id").references(() => users.id).notNull().unique(),
      // Quem foi indicado (só pode ter 1 indicação)
      refCode: text("ref_code").notNull(),
      // Código usado na indicação (user ref_code ou marketing_link code)
      status: text("status").notNull().default("PENDENTE"),
      // PENDENTE | CONFIRMADA | EXPIRADA | INVALIDA
      criadaEm: timestamp("criada_em", { withTimezone: true }).notNull().defaultNow(),
      confirmadaEm: timestamp("confirmada_em", { withTimezone: true }),
      validade: timestamp("validade", { withTimezone: true }).notNull()
      // Data limite para validação (30 dias)
    }, (table) => ({
      indicouIdx: index("indicacoes_indicou_idx").on(table.indicouId),
      indicadoIdx: uniqueIndex("indicacoes_indicado_idx").on(table.indicadoId),
      // Garante 1 indicação por indicado
      statusIdx: index("indicacoes_status_idx").on(table.status)
    }));
    indicacaoPontosLedger = pgTable("indicacao_pontos_ledger", {
      id: serial("id").primaryKey(),
      userId: integer("user_id").references(() => users.id).notNull(),
      // Quem ganhou o ponto
      indicacaoId: integer("indicacao_id").references(() => indicacoes.id, { onDelete: "cascade" }).notNull(),
      // Referência à indicação
      pontos: integer("pontos").notNull(),
      // Quantidade de pontos (geralmente 1)
      motivo: text("motivo").notNull(),
      // Ex: "indicacao_confirmada"
      criadoEm: timestamp("criado_em", { withTimezone: true }).notNull().defaultNow()
    }, (table) => ({
      userIdx: index("indicacao_pontos_user_idx").on(table.userId),
      uniqueIndicacao: uniqueIndex("indicacao_pontos_unique_idx").on(table.userId, table.indicacaoId)
      // Idempotência: 1 ponto por indicação
    }));
    stripeEvents = pgTable("stripe_events", {
      id: text("id").primaryKey(),
      // Stripe event ID
      type: text("type").notNull(),
      // Tipo do evento (ex: invoice.payment_succeeded)
      processedAt: timestamp("processed_at", { withTimezone: true }).notNull().defaultNow()
    });
    indicacoesRelations = relations(indicacoes, ({ one, many }) => ({
      indicou: one(users, {
        fields: [indicacoes.indicouId],
        references: [users.id],
        relationName: "indicou"
      }),
      indicado: one(users, {
        fields: [indicacoes.indicadoId],
        references: [users.id],
        relationName: "indicado"
      }),
      pontos: many(indicacaoPontosLedger)
    }));
    indicacaoPontosLedgerRelations = relations(indicacaoPontosLedger, ({ one }) => ({
      user: one(users, {
        fields: [indicacaoPontosLedger.userId],
        references: [users.id]
      }),
      indicacao: one(indicacoes, {
        fields: [indicacaoPontosLedger.indicacaoId],
        references: [indicacoes.id]
      })
    }));
    insertIndicacaoSchema = createInsertSchema(indicacoes).omit({
      id: true,
      criadaEm: true
    });
    insertIndicacaoPontosSchema = createInsertSchema(indicacaoPontosLedger).omit({
      id: true,
      criadoEm: true
    });
    marketingCampaigns = pgTable("marketing_campaigns", {
      id: serial("id").primaryKey(),
      name: text("name").notNull(),
      description: text("description"),
      ownerUserId: integer("owner_user_id").references(() => users.id),
      // Responsável interno (opcional)
      rewardToUserId: integer("reward_to_user_id").references(() => users.id),
      // Se todos os links creditam para 1 pessoa (opcional)
      startsAt: timestamp("starts_at", { withTimezone: true }),
      endsAt: timestamp("ends_at", { withTimezone: true }),
      isActive: boolean("is_active").notNull().default(true),
      createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow()
    }, (table) => ({
      nameIdx: index("marketing_campaigns_name_idx").on(table.name),
      isActiveIdx: index("marketing_campaigns_active_idx").on(table.isActive)
    }));
    marketingLinks = pgTable("marketing_links", {
      id: serial("id").primaryKey(),
      campaignId: integer("campaign_id").references(() => marketingCampaigns.id, { onDelete: "cascade" }),
      code: text("code").notNull().unique(),
      // Ex: MKT-AB12CD
      medium: text("medium"),
      // Ex: instagram, qr_print, whatsapp
      source: text("source"),
      // Ex: @influencerX, evento_Y
      utmSource: text("utm_source"),
      utmMedium: text("utm_medium"),
      utmCampaign: text("utm_campaign"),
      maxConversions: integer("max_conversions"),
      // Teto de conversões (opcional)
      expiresAt: timestamp("expires_at", { withTimezone: true }),
      // Expiração do link
      rewardToUserId: integer("reward_to_user_id").references(() => users.id),
      // Se definido, credita para este usuário
      metadata: jsonb("metadata"),
      // Informações extras
      createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
      isActive: boolean("is_active").notNull().default(true)
    }, (table) => ({
      codeIdx: uniqueIndex("marketing_links_code_idx").on(table.code),
      campaignIdx: index("marketing_links_campaign_idx").on(table.campaignId),
      isActiveIdx: index("marketing_links_active_idx").on(table.isActive)
    }));
    mktClicks = pgTable("mkt_clicks", {
      id: serial("id").primaryKey(),
      linkId: integer("link_id").references(() => marketingLinks.id, { onDelete: "cascade" }).notNull(),
      timestamp: timestamp("timestamp", { withTimezone: true }).notNull().defaultNow(),
      userAgent: text("user_agent"),
      ipHash: text("ip_hash"),
      // Hash do IP (sem PII)
      referer: text("referer")
    }, (table) => ({
      linkIdx: index("mkt_clicks_link_idx").on(table.linkId),
      timestampIdx: index("mkt_clicks_timestamp_idx").on(table.timestamp)
    }));
    marketingCampaignsRelations = relations(marketingCampaigns, ({ one, many }) => ({
      owner: one(users, {
        fields: [marketingCampaigns.ownerUserId],
        references: [users.id],
        relationName: "campaignOwner"
      }),
      rewardTo: one(users, {
        fields: [marketingCampaigns.rewardToUserId],
        references: [users.id],
        relationName: "campaignRewardTo"
      }),
      links: many(marketingLinks)
    }));
    marketingLinksRelations = relations(marketingLinks, ({ one, many }) => ({
      campaign: one(marketingCampaigns, {
        fields: [marketingLinks.campaignId],
        references: [marketingCampaigns.id]
      }),
      rewardTo: one(users, {
        fields: [marketingLinks.rewardToUserId],
        references: [users.id],
        relationName: "linkRewardTo"
      }),
      clicks: many(mktClicks)
    }));
    mktClicksRelations = relations(mktClicks, ({ one }) => ({
      link: one(marketingLinks, {
        fields: [mktClicks.linkId],
        references: [marketingLinks.id]
      })
    }));
    insertMarketingCampaignSchema = createInsertSchema(marketingCampaigns).omit({
      id: true,
      createdAt: true
    });
    insertMarketingLinkSchema = createInsertSchema(marketingLinks).omit({
      id: true,
      createdAt: true
    });
    insertMktClickSchema = createInsertSchema(mktClicks).omit({
      id: true,
      timestamp: true
    });
