    insertProjectSchema = createInsertSchema(projects).omit({ id: true, created_at: true, updated_at: true }).extend({
      period_start: z.coerce.date().nullable().optional(),
      period_end: z.coerce.date().nullable().optional()
    }).superRefine((data, ctx) => {
      if (data.period_end != null) {
        if (data.period_start == null) {
          ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ["period_start"],
            message: "Data de in\xEDcio \xE9 obrigat\xF3ria quando data de t\xE9rmino \xE9 informada."
          });
        } else if (data.period_end < data.period_start) {
          ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ["period_end"],
            message: "Data de t\xE9rmino deve ser igual ou posterior \xE0 data de in\xEDcio."
          });
        }
      }
    });
