      // Nome do projeto no Excel
      indicador_excel: text("indicador_excel").notNull(),
      // Nome do indicador no Excel
      meta_excel: text("meta_excel"),
      // Meta original do Excel
      recorrencia_excel: text("recorrencia_excel"),
