    inAppNotifications = pgTable("in_app_notifications", {
      id: serial("id").primaryKey(),
      title: text("title").notNull(),
      message: text("message").notNull(),
      // Botão primário (amarelo)
      primaryButtonText: text("primary_button_text"),
      primaryButtonAction: text("primary_button_action"),
      // URL ou rota do app (ex: /perfil, /editar-dados)
      // Botão secundário (preto)
      secondaryButtonText: text("secondary_button_text"),
      secondaryButtonAction: text("secondary_button_action"),
      // 'dismiss' ou rota
      // Configurações
      targetAudience: text("target_audience").default("all"),
      // 'all', 'donors', 'no_email', 'no_subscription'
      priority: integer("priority").default(1),
      // 1-10, maior = mais importante
      progressDuration: integer("progress_duration").default(5),
      // segundos para a barra encher
      // Status
      active: boolean("active").default(true),
      expiresAt: timestamp("expires_at"),
      // Enviar também como push?
      sendAsPush: boolean("send_as_push").default(false),
      pushSentAt: timestamp("push_sent_at"),
      // Tipo de notificação: normal ou com requisito (ex: pedir e-mail)
      notificationType: text("notification_type").default("normal"),
      // 'normal', 'email_required'
      // Rotas bloqueadas até o requisito ser atendido (JSON array)
      blockedRoutes: text("blocked_routes"),
      // JSON array ex: ["/beneficios", "/missoes"]
      // Campo de input para coletar (apenas para tipos com requisito)
      requirementField: text("requirement_field"),
      // 'email', 'telefone', etc
      // Agendamento
      scheduledAt: timestamp("scheduled_at"),
      // Tracking
      createdBy: integer("created_by").references(() => users.id),
      createdAt: timestamp("created_at").defaultNow(),
      updatedAt: timestamp("updated_at").defaultNow()
    });
