        const numeroAtual = ultimoIngresso ? parseInt(ultimoIngresso.numero, 10) : 0;
        const proximoNumero = Number.isFinite(numeroAtual) ? numeroAtual + 1 : 1;
        return proximoNumero.toString().padStart(3, "0");
