      async fixPatrocinadorSequence() {
        try {
          const seqResult = await db.execute(sql2`SELECT pg_get_serial_sequence('patrocinadores', 'id')`);
          const seqName = seqResult.rows?.[0]?.pg_get_serial_sequence;
          if (seqName) {
            await db.execute(sql2`SELECT setval(${seqName}, (SELECT COALESCE(MAX(id), 0) FROM patrocinadores))`);
          } else {
            await db.execute(sql2`CREATE SEQUENCE IF NOT EXISTS patrocinadores_id_seq OWNED BY patrocinadores.id`);
            await db.execute(sql2`ALTER TABLE patrocinadores ALTER COLUMN id SET DEFAULT nextval('patrocinadores_id_seq')`);
            await db.execute(sql2`SELECT setval('patrocinadores_id_seq', (SELECT COALESCE(MAX(id), 0) FROM patrocinadores))`);
          }
        } catch (error) {
          console.error("\u274C [PATROCINADORES] Erro ao fixar sequ\xEAncia:", error);
          throw error;
        }
      }
