import Stripe2 from "stripe";
import { eq as eq2 } from "drizzle-orm";
var stripeSecret = process.env.STRIPE_SECRET_KEY?.trim();
if (!stripeSecret) {
  console.warn(
    "\u26A0\uFE0F STRIPE_SECRET_KEY ausente \u2014 Stripe inicia em modo stub (ok para UI local sem pagamentos)."
  );
}
var stripe = new Stripe2(stripeSecret || "sk_test_local_dev_placeholder", {
  apiVersion: "2025-08-27.basil"
});
async function findBestActiveSubscription(stripe5, customerId) {
  const subs = await stripe5.subscriptions.list({
    customer: customerId,
    status: "all",
    limit: 20
  });
  const isActiveLike = (s) => (s.status === "active" || s.status === "trialing") && !s.pause_collection;
  const active = subs.data.find(isActiveLike);
  if (active) return { ok: true, sub: active };
  const problematic = subs.data.find(
    (s) => ["past_due", "unpaid", "incomplete", "incomplete_expired"].includes(
      s.status
    )
  );
  if (problematic) return { ok: false, sub: problematic };
  const canceled = subs.data.find((s) => s.status === "canceled");
  if (canceled) return { ok: false, sub: canceled };
  return { ok: false, sub: null };
}
function normalizePhoneToE164(phone) {
  if (!phone) return "";
  let cleaned = phone.replace(/\D/g, "");
  cleaned = cleaned.replace(/^0+/, "");
  if (cleaned.startsWith("55")) {
    cleaned = cleaned.substring(2);
  }
  if (cleaned.length === 10) {
    const ddd = cleaned.substring(0, 2);
    const numero = cleaned.substring(2);
    cleaned = `${ddd}9${numero}`;
  }
  return `+55${cleaned}`;
}
function getPhoneSearchVariants(phone) {
  if (!phone) return [];
  try {
    const e164 = normalizePhoneToE164(phone);
    const digitsOnly = e164.replace(/\D/g, "");
    const withoutCountry = digitsOnly.substring(2);
    return [e164, withoutCountry, digitsOnly];
  } catch {
    const cleaned = phone.replace(/\D/g, "");
    return cleaned ? [cleaned] : [];
  }
}
async function getOrCreateStripeCustomer(userId2, contactInfo) {
  try {
    console.log(`\u{1F50D} [GET_OR_CREATE_CUSTOMER] Iniciando para user ${userId2}`);
    const [user2] = await db.select().from(users).where(eq2(users.id, userId2)).limit(1);
    if (!user2) {
      throw new Error(`User ${userId2} n\xE3o encontrado no banco`);
    }
    if (user2.stripeCustomerId) {
      try {
        const customer2 = await stripe.customers.retrieve(user2.stripeCustomerId);
        if (!customer2.deleted && "email" in customer2) {
          console.log(
            `\u2705 [GET_OR_CREATE_CUSTOMER] Customer existente encontrado: ${user2.stripeCustomerId}`
          );
          if (!user2.email && customer2.email) {
            console.log(
              `\u{1F4E7} [GET_OR_CREATE_CUSTOMER] Salvando email do Stripe: ${customer2.email}`
            );
            await db.update(users).set({ email: customer2.email }).where(eq2(users.id, userId2));
          }
          return user2.stripeCustomerId;
        } else {
          console.warn(
            `\u26A0\uFE0F  [GET_OR_CREATE_CUSTOMER] Customer ${user2.stripeCustomerId} foi deletado, criando novo`
          );
        }
      } catch (error) {
        console.warn(
          `\u26A0\uFE0F  [GET_OR_CREATE_CUSTOMER] Customer ${user2.stripeCustomerId} inv\xE1lido, procurando outro`
        );
      }
    }
    const nome = contactInfo?.nome || user2.nome || "";
    const telefone = contactInfo?.telefone || user2.telefone || "";
    const email = contactInfo?.email || user2.email || "";
    if (telefone) {
      const phoneVariants = getPhoneSearchVariants(telefone);
      if (phoneVariants.length > 0) {
        console.log(
          `\u{1F50D} [GET_OR_CREATE_CUSTOMER] Buscando por varia\xE7\xF5es de telefone:`,
          phoneVariants
        );
        try {
          for (const variant of phoneVariants) {
            const customersByPhone = await stripe.customers.search({
              query: `phone~"${variant}"`,
              limit: 10
            });
            if (customersByPhone.data.length > 0) {
              const existingCustomer = customersByPhone.data.find(
                (c) => !c.deleted
              );
              if (existingCustomer) {
                console.log(
                  `\u2705 [GET_OR_CREATE_CUSTOMER] Customer encontrado por telefone (varia\xE7\xE3o: ${variant}): ${existingCustomer.id} (${existingCustomer.phone})`
                );
                const updateData2 = {
                  stripeCustomerId: existingCustomer.id
                };
                if (existingCustomer.email && !user2.email) {
                  updateData2.email = existingCustomer.email;
                  console.log(
                    `\u{1F4E7} [GET_OR_CREATE_CUSTOMER] Salvando email do Stripe: ${existingCustomer.email}`
                  );
                }
                await db.update(users).set(updateData2).where(eq2(users.id, userId2));
                return existingCustomer.id;
              }
            }
          }
        } catch (error) {
          console.warn(
            `\u26A0\uFE0F  [GET_OR_CREATE_CUSTOMER] Erro na busca por telefone:`,
            error
          );
        }
      }
    }
    if (email && email.includes("@")) {
      const customersByEmail = await stripe.customers.list({
        email,
        limit: 10
      });
      for (const existingCustomer of customersByEmail.data) {
        if (!existingCustomer.deleted) {
          console.log(
            `\u2705 [GET_OR_CREATE_CUSTOMER] Customer encontrado por email: ${existingCustomer.id}`
          );
          const updateData2 = { stripeCustomerId: existingCustomer.id };
          if (existingCustomer.email && !user2.email) {
            updateData2.email = existingCustomer.email;
            console.log(
              `\u{1F4E7} [GET_OR_CREATE_CUSTOMER] Salvando email do Stripe: ${existingCustomer.email}`
            );
          }
          await db.update(users).set(updateData2).where(eq2(users.id, userId2));
          return existingCustomer.id;
        }
      }
    }
    console.log(
      `\u2795 [GET_OR_CREATE_CUSTOMER] Criando novo customer para user ${userId2}`
    );
    let phoneToSave = void 0;
    if (telefone) {
      try {
        phoneToSave = normalizePhoneToE164(telefone);
        console.log(
          `\u{1F4F1} [GET_OR_CREATE_CUSTOMER] Telefone normalizado: ${telefone} \u2192 ${phoneToSave}`
        );
      } catch (error) {
        console.warn(
          `\u26A0\uFE0F  [GET_OR_CREATE_CUSTOMER] Falha ao normalizar telefone, usando original:`,
          error
        );
        phoneToSave = telefone;
      }
    }
    const newCustomer = await stripe.customers.create({
      name: nome,
      phone: phoneToSave,
      email: email && email.includes("@") ? email : void 0,
      metadata: {
        userId: String(userId2),
        source: "clube_do_grito",
        created_by: "getOrCreateStripeCustomer"
      }
    });
    console.log(
      `\u2705 [GET_OR_CREATE_CUSTOMER] Novo customer criado: ${newCustomer.id}`
    );
    const updateData = { stripeCustomerId: newCustomer.id };
    const emailToSave = email && email.includes("@") ? email : null;
    if (emailToSave && !user2.email) {
      updateData.email = emailToSave;
      console.log(`\u{1F4E7} [GET_OR_CREATE_CUSTOMER] Salvando email: ${emailToSave}`);
    }
    await db.update(users).set(updateData).where(eq2(users.id, userId2));
    return newCustomer.id;
  } catch (error) {
    console.error(`\u274C [GET_OR_CREATE_CUSTOMER] Erro:`, error);
    throw error;
  }
}
async function attachPaymentMethodSafely(paymentMethodId, customerId) {
  try {
    const pmToAttach = await stripe.paymentMethods.retrieve(paymentMethodId);
    if (!pmToAttach.card?.fingerprint) {
      await stripe.paymentMethods.attach(paymentMethodId, {
        customer: customerId
      });
      console.log(`\u2705 [ATTACH_PM] Payment method ${paymentMethodId} anexado`);
      return { attached: true, paymentMethodId };
    }
    const existingPMs = await stripe.paymentMethods.list({
      customer: customerId,
      type: "card",
      limit: 100
    });
    const duplicate = existingPMs.data.find(
      (pm) => pm.card?.fingerprint === pmToAttach.card?.fingerprint
    );
    if (duplicate) {
      console.log(
        `\u26A0\uFE0F  [ATTACH_PM] Cart\xE3o j\xE1 existe: ${duplicate.id} (fingerprint: ${pmToAttach.card.fingerprint})`
      );
      console.log(`   Usando cart\xE3o existente em vez de duplicar`);
      return { attached: false, paymentMethodId: duplicate.id };
    }
    await stripe.paymentMethods.attach(paymentMethodId, {
      customer: customerId
    });
    console.log(
      `\u2705 [ATTACH_PM] Payment method ${paymentMethodId} anexado (novo cart\xE3o)`
    );
    return { attached: true, paymentMethodId };
  } catch (error) {
    console.error(`\u274C [ATTACH_PM] Erro ao anexar payment method:`, error);
    throw error;
  }
}

