// server/lib/safeError.ts
var isProd = process.env.NODE_ENV === "production";
function toClientError(err, fallback = "Erro interno do servidor") {
  if (!isProd) {
    if (err instanceof Error) return err.message;
    return String(err);
  }
  return fallback;
}
function safeErrorPayload(err, fallback = "Erro interno do servidor") {
  if (err instanceof Error) {
    console.error("[API]", err.message, isProd ? "" : err.stack);
  } else {
    console.error("[API]", err);
  }
  return { error: toClientError(err, fallback) };
}

// server/services/cieloService.ts
function getConfig() {
  const merchantId = (process.env.CIELO_MERCHANT_ID ?? "").trim();
  const merchantKey = (process.env.CIELO_MERCHANT_KEY ?? "").trim();
  if (!merchantId || !merchantKey) {
    throw new Error("Credenciais Cielo n\xE3o configuradas (CIELO_MERCHANT_ID / CIELO_MERCHANT_KEY)");
  }
  return {
    merchantId,
    merchantKey,
    sandbox: process.env.CIELO_ENV !== "prod"
  };
}
function getBaseUrl(config, queryApi = false) {
  if (config.sandbox) {
    return queryApi ? "https://apiquerysandbox.cieloecommerce.cielo.com.br" : "https://apisandbox.cieloecommerce.cielo.com.br";
  }
  return queryApi ? "https://apiquery.cieloecommerce.cielo.com.br" : "https://api.cieloecommerce.cielo.com.br";
}
async function callCielo(path5, method, body, useQueryUrl = false, requestId) {
  const config = getConfig();
  const baseUrl = getBaseUrl(config, useQueryUrl);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 25e3);
  try {
    const resp = await fetch(`${baseUrl}${path5}`, {
      method,
      headers: {
        "Content-Type": "application/json",
        MerchantId: config.merchantId,
        MerchantKey: config.merchantKey,
        ...requestId ? { RequestId: requestId } : {}
      },
      body: body ? JSON.stringify(body) : void 0,
      signal: controller.signal
    });
    clearTimeout(timer);
    const text2 = await resp.text();
    let data;
    try {
      data = JSON.parse(text2);
    } catch {
      data = { raw: text2 };
    }
    return { status: resp.status, data };
  } catch (e) {
    clearTimeout(timer);
    if (e.name === "AbortError") throw new Error("Timeout na comunica\xE7\xE3o com a Cielo (>25s)");
    throw e;
  }
}
function detectBrand(cardNumber) {
  const n = cardNumber.replace(/\D/g, "");
  if (/^4/.test(n)) return "Visa";
  if (/^(5[1-5]|2(2[2-9]|[3-6]\d|7[01]))/.test(n)) return "Master";
  if (/^3[47]/.test(n)) return "Amex";
  if (/^(6362|636368|438935|504175|451416|636297|5067|4576|4011)/.test(n)) return "Elo";
  if (/^(606282|3841)/.test(n)) return "Hipercard";
  if (/^(301|305|3095|36|38)/.test(n)) return "Diners";
  return "Visa";
}
function mapCieloStatus(cieloStatus) {
  switch (cieloStatus) {
    case 0:
      return "created";
    case 1:
      return "processing";
    case 2:
      return "paid";
    case 3:
      return "denied";
    case 10:
      return "cancelled";
    case 11:
      return "cancelled";
    case 12:
      return "pending";
    case 13:
      return "cancelled";
    case 20:
      return "cancelled";
    default:
      return "error";
  }
}
function maskCpf(cpf) {
  const c = cpf.replace(/\D/g, "");
  return c.length >= 11 ? `${c.slice(0, 3)}.***.***-${c.slice(-2)}` : "***";
}
async function createCardPayment(input) {
  const { orderRef, idempotencyKey, valorTotal, parcelas, titular, cartao } = input;
  const [mm, aa] = cartao.validade.split("/");
  const expiryFull = aa ? `${mm}/20${aa.slice(-2)}` : cartao.validade;
  console.log(`[CIELO] Cart\xE3o - Ref:${orderRef} Valor:${valorTotal} Parcelas:${parcelas} CPF:${maskCpf(titular.cpf)}`);
  const payload = {
    MerchantOrderId: orderRef,
    Customer: {
      Name: titular.nome,
      Identity: titular.cpf.replace(/\D/g, ""),
      IdentityType: "CPF",
      Email: titular.email
    },
    Payment: {
      Type: "CreditCard",
      Amount: valorTotal,
      Installments: Math.min(10, Math.max(1, parcelas)),
      Capture: true,
      Interest: "ByMerchant",
      SoftDescriptor: "Instituto O Grito",
      CreditCard: {
        CardNumber: cartao.numero.replace(/\D/g, ""),
        Holder: cartao.titular.toUpperCase().trim(),
        ExpirationDate: expiryFull,
        SecurityCode: cartao.cvv,
        Brand: cartao.bandeira,
        SaveCard: false
      }
    }
  };
  const requestId = (idempotencyKey || orderRef).slice(0, 50);
  const { status: httpStatus, data } = await callCielo("/1/sales", "POST", payload, false, requestId);
  if (httpStatus === 401) {
    console.error(`[CIELO] N\xE3o autorizado (401) Ref:${orderRef} Verifique MerchantId/MerchantKey e ambiente CIELO_ENV`);
    throw new Error("Cielo n\xE3o autorizou a requisi\xE7\xE3o (401). Verifique CIELO_MERCHANT_ID, CIELO_MERCHANT_KEY e CIELO_ENV.");
  }
  if (httpStatus >= 500) {
    console.error(`[CIELO] Erro servidor Ref:${orderRef} HTTP:${httpStatus}`);
    throw new Error("Erro no servidor da Cielo. Tente novamente.");
  }
  const payment = data?.Payment;
  if (!payment) {
    console.error(`[CIELO] Resposta sem Payment - HTTP:${httpStatus} Ref:${orderRef} Body:${JSON.stringify(data)}`);
    throw new Error("Resposta inv\xE1lida da Cielo");
  }
  const cieloStatus = payment.Status ?? -1;
  const status = mapCieloStatus(cieloStatus);
  console.log(`[CIELO] Cart\xE3o - Status:${cieloStatus}(${status}) Ref:${orderRef} ReturnCode:${payment.ReturnCode}`);
  return {
    paymentId: payment.PaymentId,
    status,
    cieloStatus,
    returnCode: payment.ReturnCode,
    returnMessage: payment.ReturnMessage,
    authorizationCode: payment.AuthorizationCode
  };
}
