function validarFormatoSenhaManual(senha) {
  const s = String(senha || "");
  if (s.length < 8) return "A senha deve ter no m\xEDnimo 8 caracteres.";
  if (s.length > 64) return "A senha deve ter no m\xE1ximo 64 caracteres.";
  if (!/[a-zA-Z]/.test(s) || !/[0-9]/.test(s)) {
    return "A senha deve ser alfanum\xE9rica (letras e n\xFAmeros).";
  }
  return null;
}
