function lerMetasPlanilha() {
  const planilhaPath = "server/data/PLANEJAMENTO FINANCEIRO 2025 COM FAVELA (1)_1759772504530.xlsx";
  console.log("\u{1F4CA} [PLANILHA] Lendo metas financeiras de:", planilhaPath);
  try {
    const workbook = XLSX3.readFile(planilhaPath);
    const sheet = workbook.Sheets["GERAL"];
    if (!sheet) {
      throw new Error("Aba GERAL n\xE3o encontrada na planilha");
    }
    const data = XLSX3.utils.sheet_to_json(sheet, {
      header: 1,
      defval: ""
    });
    const receitas = [];
    const despesas = [];
    let blocoAtual = null;
    for (let i = 0; i < data.length; i++) {
      const row = data[i];
      if (row[1] === "RECEITAS") {
        blocoAtual = "RECEITAS";
        console.log(
          `\u2705 [PLANILHA] Bloco RECEITAS encontrado na linha ${i + 1}`
        );
        continue;
      }
      if (row[1] === "DESPESAS") {
        blocoAtual = "DESPESAS";
        console.log(
          `\u2705 [PLANILHA] Bloco DESPESAS encontrado na linha ${i + 1}`
        );
        continue;
      }
      if (!blocoAtual || !row[1] || typeof row[1] !== "string") {
        continue;
      }
      const categoria = row[1].trim();
      if (categoria === "" || categoria === blocoAtual) {
        continue;
      }
      const metas = {
        janeiro: parseFloat(row[2]) || 0,
        fevereiro: parseFloat(row[3]) || 0,
        marco: parseFloat(row[4]) || 0,
        abril: parseFloat(row[5]) || 0,
        maio: parseFloat(row[6]) || 0,
        junho: parseFloat(row[7]) || 0,
        julho: parseFloat(row[8]) || 0,
        agosto: parseFloat(row[9]) || 0,
        setembro: parseFloat(row[10]) || 0,
        outubro: parseFloat(row[11]) || 0,
        novembro: parseFloat(row[12]) || 0,
        dezembro: parseFloat(row[13]) || 0,
        total: parseFloat(row[14]) || 0
      };
      const metaCategoria = {
        categoria,
        grupo: blocoAtual,
        metas
      };
      if (blocoAtual === "RECEITAS") {
        receitas.push(metaCategoria);
      } else {
        despesas.push(metaCategoria);
      }
    }
    console.log(
      `\u2705 [PLANILHA] Metas extra\xEDdas: ${receitas.length} categorias de RECEITAS, ${despesas.length} categorias de DESPESAS`
    );
    return {
      receitas,
      despesas,
      timestamp: (/* @__PURE__ */ new Date()).toISOString()
    };
  } catch (error) {
    console.error("\u274C [PLANILHA] Erro ao ler planilha:", error);
    throw error;
  }
}
async function obterDadosDepartamentoDoBanco(departamento, ano = 2025) {
  console.log(
    `\u{1F4CA} [DEPARTAMENTO DB ANUAL] Buscando dados anuais do banco para: ${departamento}, ano: ${ano}`
  );
  const departamentoNormalizado = departamento.toUpperCase();
  const dadosAnuais = await db.select().from(conselhoDadosRealizadosAnual).where(
    and2(
      eq9(conselhoDadosRealizadosAnual.ano, ano),
      sql4`UPPER(${conselhoDadosRealizadosAnual.departamento}) = ${departamentoNormalizado}`
    )
  );
  if (dadosAnuais.length > 0) {
    const dados = dadosAnuais[0];
    const contasReceber = parseFloat(dados.contasAReceber?.toString() || "0");
    const contasPagar = Math.abs(
      parseFloat(dados.contasAPagar?.toString() || "0")
    );
    const saldo = parseFloat(dados.saldo?.toString() || "0");
    console.log(
      `\u2705 [DEPARTAMENTO DB ANUAL] ${departamento}: Receber=R$ ${contasReceber.toFixed(
        2
      )}, Pagar=R$ ${contasPagar.toFixed(2)}, Saldo=R$ ${saldo.toFixed(2)}`
    );
    return {
      departamento,
      contasReceber,
      contasPagar,
      saldo
    };
  }
  console.log(
    `\u26A0\uFE0F [DEPARTAMENTO DB ANUAL] Nenhum dado anual encontrado para: ${departamento}`
  );
  return {
    departamento,
    contasReceber: 0,
    contasPagar: 0,
    saldo: 0
  };
}
