async function obterMetasDepartamento(departamento, ano = 2025) {
  try {
    let departamentoLimpo = departamento.replace(/&amp;/g, "&");
    departamentoLimpo = departamentoLimpo.replace(/ e /gi, " & ");
    console.log(
      `\u{1F9F9} [DECODE+NORM] "${departamento}" \u2192 "${departamentoLimpo}" (${Date.now()})`
    );
    const departamentoEscaped = departamentoLimpo.replace(/'/g, "''");
    const rawQuery = `SELECT * FROM conselho_metas_mensais WHERE departamento = '${departamentoEscaped}' AND ano = ${ano} ORDER BY mes`;
    const result = await pool.query(rawQuery);
    console.log(
      `\u2705 [METAS DB] ${result.rows.length} registros para "${departamentoLimpo}"`
    );
    const metas = result.rows;
    if (!metas || metas.length === 0) {
      console.log(
        `\u{1F50D} [obterMetasDepartamento] Nenhuma meta encontrada no banco para "${departamento}"`
      );
      return null;
    }
    console.log(
      `\u2705 [obterMetasDepartamento] ${metas.length} metas encontradas no banco`
    );
    const metasMensais = {
      contasReceber: {
        janeiro: 0,
        fevereiro: 0,
        marco: 0,
        abril: 0,
        maio: 0,
        junho: 0,
        julho: 0,
        agosto: 0,
        setembro: 0,
        outubro: 0,
        novembro: 0,
        dezembro: 0
      },
      contasPagar: {
        janeiro: 0,
        fevereiro: 0,
        marco: 0,
        abril: 0,
        maio: 0,
        junho: 0,
        julho: 0,
        agosto: 0,
        setembro: 0,
        outubro: 0,
        novembro: 0,
        dezembro: 0
      }
    };
    const mesesMap = [
      "janeiro",
      "fevereiro",
      "marco",
      "abril",
      "maio",
      "junho",
      "julho",
      "agosto",
      "setembro",
      "outubro",
      "novembro",
      "dezembro"
    ];
    for (const meta of metas) {
      const mesNome = mesesMap[meta.mes - 1];
      metasMensais.contasReceber[mesNome] = Number(meta.meta_contas_a_receber);
      metasMensais.contasPagar[mesNome] = Number(meta.meta_contas_a_pagar);
    }
    return metasMensais;
  } catch (error) {
    console.error(`\u274C [obterMetasDepartamento] Erro ao buscar metas:`, error);
    return null;
  }
}
async function findExistingDonor({
  subscriptionId,
  customerId
}) {
  const conditions = [];
  if (subscriptionId) {
    conditions.push(eq9(doadores.stripeSubscriptionId, subscriptionId));
  }
  if (customerId) {
    conditions.push(eq9(doadores.stripeCustomerId, customerId));
  }
  if (conditions.length === 0) {
    return null;
  }
  const query = conditions.length === 1 ? db.select().from(doadores).where(conditions[0]) : db.select().from(doadores).where(or3(...conditions));
  const result = await query.limit(1);
  return result[0] || null;
}
