  app2.get("/uploads/:filename", requireAuth, (req, res) => {
    const safe = path2.basename(req.params.filename);
    if (!safe || safe.includes("..")) {
      return res.status(400).json({ error: "Nome do arquivo inv\xE1lido" });
    }
    const filePath = path2.resolve(process.cwd(), "uploads", safe);
    const uploadsRoot = path2.resolve(process.cwd(), "uploads");
    if (!filePath.startsWith(uploadsRoot + path2.sep)) {
      return res.status(400).json({ error: "Caminho inv\xE1lido" });
    }
    if (!fs2.existsSync(filePath)) {
      return res.sendStatus(404);
    }
    res.setHeader("X-Content-Type-Options", "nosniff");
    res.setHeader("Content-Disposition", "inline");
    res.setHeader("Cache-Control", "private, max-age=3600");
    return res.sendFile(filePath);
  });
  app2.get("/uploads/*", requireAuth, async (req, res) => {
    try {
      const objectName = req.path.slice(1);
      const localAbs = resolveLocalUploadPath(objectName);
      if (localAbs && fs2.existsSync(localAbs)) {
        res.setHeader("X-Content-Type-Options", "nosniff");
        res.setHeader("Content-Disposition", "inline");
        res.setHeader("Cache-Control", "private, max-age=3600");
        return res.sendFile(localAbs);
      }
      if (!isGCSAvailable || !bucket) {
        return res.status(404).send("Arquivo n\xE3o encontrado");
      }
      const [signedUrl] = await bucket.file(objectName).getSignedUrl({
        version: "v4",
        action: "read",
        expires: Date.now() + 5 * 60 * 1e3
      });
      return res.redirect(302, signedUrl);
    } catch (err) {
      console.error("\u274C /uploads/* Signed URL error:", err);
      return res.status(404).send("Arquivo n\xE3o encontrado");
    }
  });
