  app2.post("/api/checkout/subscribe", async (req, res) => {
    try {
      const {
        tier = "PLATINUM",
        amountMonthly,
        intervalMonths = 1,
        paymentMethod = "card"
      } = req.body;
      console.log("\u{1F4B0} [CHECKOUT SUBSCRIBE] Iniciando checkout RECORRENTE:", {
        tier,
        amountMonthly,
        intervalMonths,
        paymentMethod
      });
      if (!amountMonthly || typeof amountMonthly !== "number") {
        return res.status(400).json({
          error: "Campo amountMonthly \xE9 obrigat\xF3rio e deve ser um n\xFAmero"
        });
      }
      if (amountMonthly < 35 || amountMonthly > 5e4) {
        return res.status(400).json({
          error: "Valor mensal deve estar entre R$ 35,00 e R$ 50.000,00"
        });
      }
      if (![1, 3, 6, 12].includes(intervalMonths)) {
        return res.status(400).json({
          error: "Periodicidade inv\xE1lida. Valores aceitos: 1, 3, 6, 12"
        });
      }
      if (paymentMethod !== "card") {
        return res.status(400).json({
          error: "Por enquanto, apenas pagamento com cart\xE3o \xE9 suportado"
        });
      }
      const amountInCents = Math.round(amountMonthly * 100);
      const stripeIntervalMap = {
        1: "month",
        // Mensal
        3: "month",
        // Trimestral (interval_count: 3)
        6: "month",
        // Semestral (interval_count: 6)
        12: "year"
        // Anual
      };
      const stripeInterval = stripeIntervalMap[intervalMonths];
      const intervalCount = intervalMonths === 12 ? 1 : intervalMonths;
      const periodicityMap = {
        1: "Mensal",
        3: "Trimestral",
        6: "Semestral",
        12: "Anual"
      };
      const line_items = [
        {
          price_data: {
            currency: "brl",
            product_data: {
              name: `Plano ${tier} - Contribui\xE7\xE3o ${periodicityMap[intervalMonths]}`,
              description: `Cobran\xE7a autom\xE1tica ${periodicityMap[intervalMonths].toLowerCase()} de R$ ${amountMonthly.toFixed(2).replace(".", ",")}`
            },
            unit_amount: amountInCents,
            recurring: {
              interval: stripeInterval,
              interval_count: intervalCount
            }
          },
          quantity: 1
        }
      ];
      const origin = req.headers.origin || `https://${req.headers.host}` || "https://localhost:5000";
      const session2 = await stripe4.checkout.sessions.create({
        mode: "subscription",
        // SUBSCRIPTION RECORRENTE
        payment_method_types: ["card"],
        line_items,
        success_url: `${origin}/success?session_id={CHECKOUT_SESSION_ID}`,
        cancel_url: `${origin}/plans`,
        metadata: {
          tier,
          amountMonthly: amountMonthly.toString(),
          intervalMonths: intervalMonths.toString(),
          customSubscription: "true"
        }
      });
      console.log(
        "\u2705 [CHECKOUT SUBSCRIBE] Subscription recorrente criada:",
        session2.id
      );
      res.json({
        checkoutUrl: session2.url,
        sessionId: session2.id,
        status: "pending"
      });
    } catch (error) {
      console.error("\u274C [CHECKOUT SUBSCRIBE] Erro:", error);
      res.status(500).json({
        error: "Erro ao criar sess\xE3o de checkout",
        message: error.message
      });
    }
  });
  app2.post("/api/stripe/webhook", async (req, res) => {
    const sig = req.headers["stripe-signature"];
    const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;
    if (!endpointSecret) {
      console.error("\u{1F6A8} WEBHOOK ERROR: STRIPE_WEBHOOK_SECRET n\xE3o configurado");
      return res.status(503).json({ error: "Webhook endpoint secret not configured" });
    }
    if (!sig) {
      return res.status(400).json({ error: "Missing stripe signature" });
    }
    let event;
    try {
      const rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.from(typeof req.body === "string" ? req.body : JSON.stringify(req.body), "utf8");
      event = stripe4.webhooks.constructEvent(rawBody, sig, endpointSecret);
    } catch (err) {
      console.error("\u274C [WEBHOOK] Signature verification failed:", err);
      return res.status(400).send(`Webhook Error: ${err}`);
    }
    try {
      if (event.type === "checkout.session.completed") {
        const session2 = event.data.object;
        if (session2.metadata?.type === "ingresso") {
          const nome = session2.metadata.nome || session2.customer_details?.name || null;
          const email = session2.metadata.email || session2.customer_details?.email || null;
          const telefone = session2.metadata.telefone || null;
          const jaExiste = await storage.getIngressoBySessionId(session2.id);
          if (!jaExiste) {
            const ingresso = await storage.createIngresso({
              userId: null,
              nomeComprador: nome,
              emailComprador: email,
              telefoneComprador: telefone,
              idCotaEmpresa: null,
              // AVULSO
              eventoNome: "IV ENCONTRO Do Grito",
              eventoData: "23 Outubro de 2025",
              eventoHora: "19h30",
              stripeCheckoutSessionId: session2.id,
              valorPago: session2.amount_total ?? 1e5,
              status: "confirmado"
            });
            console.log(
              "\u2705 [WEBHOOK] Ingresso criado (avulso):",
              ingresso.numero
            );
          } else {
            console.log(
              "\u2139\uFE0F [WEBHOOK] Ingresso j\xE1 existia para session:",
              session2.id
            );
          }
        }
      }
      return res.status(200).json({ received: true });
    } catch (err) {
      console.error("\u274C [WEBHOOK] Erro ao processar:", err);
      try {
        const fa = app2._fireTechnicalAlert;
        if (fa) fa("webhook_falhou", err, { integracao: "Stripe", origem: "webhook/ingresso", endpoint: "/api/stripe/webhook", severidade: "alta" });
      } catch {
      }
      return res.status(500).json({ error: "Erro no processamento do webhook" });
    }
  });
