  app2.get("/api/colaboradores", async (req, res) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const pageSize = parseInt(req.query.pageSize) || 100;
      const offset = (page - 1) * pageSize;
      const search = (req.query.search || "").trim();
      const includeInactive = req.query.includeInactive === "true" || req.query.includeInactive === "1";
      let query = includeInactive ? "SELECT * FROM colaboradores WHERE 1=1" : "SELECT * FROM colaboradores WHERE ativo = true";
      const params = [];
      if (search) {
        params.push(`%${search}%`);
        query += ` AND nome ILIKE $${params.length}`;
      }
      query += " ORDER BY nome";
      const result = await pool.query(query, params);
      const colaboradoresList = result.rows || [];
      const total = colaboradoresList.length;
      const paginatedList = colaboradoresList.slice(offset, offset + pageSize);
      res.json({
        total,
        items: paginatedList.map((c) => ({
          id: c.id,
          nome: c.nome,
          telefone: c.telefone,
          email: c.email,
          departamento: c.departamento,
          vinculo: c.vinculo,
          cargo: c.cargo,
          setor: c.setor,
          ativo: c.ativo
        }))
      });
    } catch (error) {
      console.error("\u274C [COLABORADORES] Erro:", error);
      res.status(500).json({
        error: "Erro ao buscar colaboradores",
        message: error.message
      });
    }
  });
