  app2.post("/api/add-council-member", async (req, res) => {
    try {
      const { phone, email, addedBy } = req.body;
      if (!phone && !email) {
        return res.status(400).json({ error: "Phone or email is required" });
      }
      let user2;
      if (phone) {
        user2 = await storage.getUserByTelefone(phone);
      } else if (email) {
        user2 = await storage.getUserByEmail(email);
      }
      if (!user2 && phone) {
        user2 = await storage.createUser({
          cpf: null,
          // CPF é único na tabela users; placeholder fixo causava conflito
          nome: "Membro do Conselho",
          telefone: phone,
          email: email || "",
          role: "conselho",
          verificado: true,
          conselhoStatus: "aprovado"
        });
      } else if (user2) {
        await storage.updateCouncilAccessStatus(user2.telefone, "approved");
        user2 = await storage.getUserByTelefone(user2.telefone);
      }
      res.json({
        success: true,
        message: "Member added successfully",
        member: user2
      });
    } catch (error) {
      console.error("Error adding council member:", error);
      res.status(500).json({ error: "Error adding member" });
    }
  });
