  app2.post("/api/monitor/inclusao/participantes", requireAuth, requireMonitor, async (req, res) => {
    try {
      const user2 = req.user;
      const { turmaIds, ...participanteData } = req.body;
      console.log(`\u{1F4DD} [MONITOR INCLUS\xC3O] Monitor ${user2.id} criando novo participante: ${participanteData.nome}`);
      if (!participanteData.nome) {
        return res.status(400).json({ error: "O nome do participante \xE9 obrigat\xF3rio." });
      }
      if (!participanteData.genero) {
        return res.status(400).json({ error: "O g\xEAnero do participante \xE9 obrigat\xF3rio." });
      }
      if (!participanteData.idade) {
        return res.status(400).json({ error: "A idade do participante \xE9 obrigat\xF3ria." });
      }
      if (participanteData.dataIngresso) {
        participanteData.dataIngresso = new Date(participanteData.dataIngresso);
      }
      if (participanteData.dataEntrada && typeof participanteData.dataEntrada === "string") {
        participanteData.dataEntrada = new Date(participanteData.dataEntrada);
      }
      const jsonbArrayFields = [
        "telefonesAdicionais",
        "contatosEmergencia",
        "documentosPossui",
        "demandas",
        "turnoEscolar",
        "trabalhosAtuais",
        "experienciasProfissionais",
        "jaTeveOuCostumaTer",
        "relacionamentosFamiliares",
        "outrosRelacionamentos"
      ];
      jsonbArrayFields.forEach((field) => {
        if (participanteData[field] === "[]" || participanteData[field] === "") {
          participanteData[field] = [];
        } else if (typeof participanteData[field] === "string") {
          try {
            participanteData[field] = JSON.parse(participanteData[field]);
          } catch (e) {
            participanteData[field] = [];
          }
        }
      });
      ["email", "cpf", "telefone", "codigoMatricula", "identificador", "dataIngresso", "dataEntrada"].forEach((field) => {
        if (participanteData[field] === "") {
          participanteData[field] = null;
        }
      });
      if (participanteData.cpf && typeof participanteData.cpf === "string") {
        participanteData.cpf = participanteData.cpf.replace(/\D/g, "");
      }
      const validationResult = insertParticipanteInclusaoSchema.safeParse({
        ...participanteData
      });
      if (!validationResult.success) {
        return res.status(400).json({
          error: "Alguns dados est\xE3o incorretos. Verifique os campos e tente novamente.",
          details: validationResult.error.errors
        });
      }
      const participante = await storage.createParticipante(validationResult.data, turmaIds);
      try {
        await syncParticipanteInclusaoStatus(participante.id);
      } catch (e) {
        console.warn("\u26A0\uFE0F N\xE3o foi poss\xEDvel sincronizar status do participante:", e);
      }
      try {
        const vinculoExistente = await db.select().from(psicoInclusaoVinculo).where(eq9(psicoInclusaoVinculo.participanteInclusaoId, participante.id)).limit(1);
        if (vinculoExistente.length === 0) {
          const [novaFamilia] = await db.insert(psicoFamilias).values({
            nomeResponsavel: participante.nome,
            numeroMembros: 1,
            telefone: participante.telefone || null,
            endereco: participante.endereco || null,
            status: "ativo",
            coordenadorId: user2.id,
            observacoes: `Fam\xEDlia criada automaticamente - Monitor Inclus\xE3o: ${participante.nome}`
          }).returning();
          await db.insert(psicoInclusaoVinculo).values({
            participanteInclusaoId: participante.id,
            psicoFamiliaId: novaFamilia.id,
            papel: "atendido",
            observacoes: "V\xEDnculo criado automaticamente ao cadastrar participante via Monitor"
          });
          console.log(`\u2705 [MONITOR INCLUS\xC3O\u2192PSICO] Participante ${participante.id} vinculado \xE0 fam\xEDlia ${novaFamilia.id}`);
        }
      } catch (vinculoError) {
        console.error("\u26A0\uFE0F [MONITOR INCLUS\xC3O\u2192PSICO] Erro ao criar v\xEDnculo autom\xE1tico:", vinculoError);
      }
      console.log(`\u2705 [MONITOR INCLUS\xC3O] Participante criado com sucesso: ID ${participante.id}`);
      res.status(201).json(participante);
    } catch (error) {
      console.error("\u274C [MONITOR INCLUS\xC3O] Erro ao criar participante:", error);
      const pgErr = formatPostgresError(error, "participante");
      res.status(pgErr.status).json({ error: pgErr.message });
    }
  });
