  app2.put("/api/coordenador/professor-turmas/:turmaId", express.json(), async (req, res) => {
    try {
      const turmaId = parseInt(req.params.turmaId);
      const { professorIds, professores: professores3, turmaTipo } = req.body;
      if (!turmaTipo) return res.status(400).json({ error: "turmaTipo \xE9 obrigat\xF3rio" });
      await pool.query(
        "DELETE FROM professor_turmas WHERE turma_id = $1 AND turma_tipo = $2",
        [turmaId, turmaTipo]
      );
      const profsToInsert = [];
      if (Array.isArray(professores3) && professores3.length > 0) {
        professores3.forEach((p) => profsToInsert.push({ id: p.id || p.professorId, cor: p.cor || null, icone: p.icone || null }));
      } else if (Array.isArray(professorIds) && professorIds.length > 0) {
        professorIds.forEach((pid) => profsToInsert.push({ id: pid }));
      }
      if (profsToInsert.length > 0) {
        const insertValues = profsToInsert.map(
          (_, i) => `($${i * 5 + 1}, $${i * 5 + 2}, $${i * 5 + 3}, $${i * 5 + 4}, $${i * 5 + 5})`
        ).join(", ");
        const insertParams = profsToInsert.flatMap((p) => [p.id, turmaId, turmaTipo, p.cor || null, p.icone || null]);
        await pool.query(
          `INSERT INTO professor_turmas (professor_id, turma_id, turma_tipo, cor, icone) VALUES ${insertValues}
           ON CONFLICT (professor_id, turma_id, turma_tipo) DO UPDATE SET cor = EXCLUDED.cor, icone = EXCLUDED.icone`,
          insertParams
        );
      }
      res.json({ success: true });
    } catch (error) {
      console.error("\u274C [PUT /api/coordenador/professor-turmas/:turmaId] Erro:", error);
      res.status(500).json({ error: "Erro ao atualizar professores da turma" });
    }
  });
