  app2.get("/api/inclusao/frequencia-turmas", requireAuth, async (req, res) => {
    try {
      const dataInicio = req.query.dataInicio;
      const dataFim = req.query.dataFim;
      const dateFilter = dataInicio && dataFim ? `AND pi.data >= '${dataInicio}'::date AND pi.data <= '${dataFim}'::date` : "";
      const result = await pool.query(`
        SELECT
          ti.id                                               AS turma_id,
          ti.nome                                             AS turma_nome,
          COUNT(CASE WHEN pi.id IS NOT NULL AND NOT (pi.presente = false AND pi.justificativa IS NOT NULL AND pi.justificativa != '' AND pi.justificativa != 'Sem justificativa') THEN 1 END) AS total_registros,
          COUNT(CASE WHEN pi.presente = true THEN 1 END)      AS presentes
        FROM turmas_inclusao ti
        LEFT JOIN presencas_inclusao pi ON pi.turma_id = ti.id ${dateFilter}
        GROUP BY ti.id, ti.nome
        ORDER BY ti.nome
      `);
      const turmas = result.rows.map((r) => {
        const total = Number(r.total_registros);
        const pres = Number(r.presentes);
        return {
          turmaId: r.turma_id,
          turmaNome: r.turma_nome,
          totalRegistros: total,
          presentes: pres,
          frequencia: total > 0 ? Math.round(pres / total * 1e3) / 10 : 0
        };
      }).filter((t) => t.totalRegistros > 0);
      const totalReg = turmas.reduce((s, t) => s + t.totalRegistros, 0);
      const totalPres = turmas.reduce((s, t) => s + t.presentes, 0);
      res.json({
        turmas,
        geral: {
          totalRegistros: totalReg,
          presentes: totalPres,
          frequencia: totalReg > 0 ? Math.round(totalPres / totalReg * 1e3) / 10 : 0
        }
      });
    } catch (err) {
      console.error("Erro frequencia-turmas Inclus\xE3o:", err);
      res.status(500).json({ error: "Erro ao calcular frequ\xEAncia" });
    }
  });
