  app2.get("/api/pec/activity-instances/:id/dias-aula", requireAuth, async (req, res) => {
    try {
      const instanceId = parseInt(req.params.id);
      if (isNaN(instanceId)) return res.status(400).json({ error: "id inv\xE1lido" });
      const [inst] = await db.select().from(activityInstances).where(eq9(activityInstances.id, instanceId)).limit(1);
      if (!inst) return res.status(404).json({ error: "Turma n\xE3o encontrada" });
      const diasSemana = inst.dias_semana || [];
      const occStart = inst.occurrence_start;
      const occEnd = inst.occurrence_end;
      if (!occStart || !occEnd || diasSemana.length === 0) {
        return res.json({ dias: [] });
      }
      const DAY_MAP = {
        domingo: 0,
        segunda: 1,
        "segunda-feira": 1,
        terca: 2,
        "ter\xE7a": 2,
        "ter\xE7a-feira": 2,
        quarta: 3,
        "quarta-feira": 3,
        quinta: 4,
        "quinta-feira": 4,
        sexta: 5,
        "sexta-feira": 5,
        sabado: 6,
        "s\xE1bado": 6
      };
      const normDia = (s) => s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      const jsDays = diasSemana.map((d) => {
        const norm = normDia(d);
        return DAY_MAP[norm] ?? DAY_MAP[norm.split("-")[0]] ?? -1;
      }).filter((d) => d >= 0);
      const dias = [];
      const current = /* @__PURE__ */ new Date(occStart + "T00:00:00");
      const end = /* @__PURE__ */ new Date(occEnd + "T00:00:00");
      while (current <= end) {
        if (jsDays.includes(current.getDay())) {
          dias.push(current.toISOString().split("T")[0]);
        }
        current.setDate(current.getDate() + 1);
      }
      res.json({ dias });
    } catch (error) {
      console.error("Erro ao buscar dias de aula PEC:", error);
      res.status(500).json({ error: "Erro ao buscar dias de aula PEC" });
    }
  });
