  app2.get("/api/inclusao-produtiva/administrativo", async (req, res) => {
    try {
      console.log(
        "\u{1F4CA} [INCLUS\xC3O-PRODUTIVA] Buscando cursos de Administrativo..."
      );
      const cursos2 = await db.select().from(cursosAdministrativo).orderBy(cursosAdministrativo.id);
      const cursosPresencial = cursos2.filter(
        (c) => c.modalidade === "Presencial"
      );
      const cursosEAD = cursos2.filter((c) => c.modalidade === "EAD");
      const presencialInscritos = cursosPresencial.reduce(
        (sum, c) => sum + (c.inscritos || 0),
        0
      );
      const presencialEvasao = cursosPresencial.reduce(
        (sum, c) => sum + (c.evasao || 0),
        0
      );
      const presencial = {
        cursos: cursosPresencial,
        totais: {
          inscritos: presencialInscritos,
          formados: cursosPresencial.reduce(
            (sum, c) => sum + (c.formados || 0),
            0
          ),
          evasao: presencialEvasao,
          percentualEvasao: presencialInscritos > 0 ? Math.round(presencialEvasao / presencialInscritos * 100) : 0
        }
      };
      const eadInscritos = cursosEAD.reduce(
        (sum, c) => sum + (c.inscritos || 0),
        0
      );
      const eadEvasao = cursosEAD.reduce((sum, c) => sum + (c.evasao || 0), 0);
      const ead = {
        cursos: cursosEAD,
        totais: {
          inscritos: eadInscritos,
          formados: cursosEAD.reduce((sum, c) => sum + (c.formados || 0), 0),
          evasao: eadEvasao,
          percentualEvasao: eadInscritos > 0 ? Math.round(eadEvasao / eadInscritos * 100) : 0
        }
      };
      console.log(
        `\u2705 [INCLUS\xC3O-PRODUTIVA] Administrativo - Presencial: ${cursosPresencial.length} cursos, EAD: ${cursosEAD.length} cursos`
      );
      res.json({
        success: true,
        data: { presencial, ead }
      });
    } catch (error) {
      console.error(
        "\u274C [INCLUS\xC3O-PRODUTIVA] Erro ao buscar cursos de Administrativo:",
        error
      );
      res.status(500).json({
        error: "Erro ao buscar cursos de Administrativo",
        message: error.message
      });
    }
  });
