  app2.get("/api/inclusao-produtiva/breakdown-programas", async (req, res) => {
    try {
      const ano = parseInt(req.query.ano) || (/* @__PURE__ */ new Date()).getFullYear();
      const mes = req.query.mes ? parseInt(req.query.mes) : 0;
      const trimestre = req.query.trimestre ? parseInt(req.query.trimestre) : 0;
      const mesInicio = trimestre >= 1 && trimestre <= 4 ? (trimestre - 1) * 3 + 1 : mes > 0 ? mes : 1;
      const mesFim = trimestre >= 1 && trimestre <= 4 ? trimestre * 3 : mes > 0 ? mes : 12;
      const result = await pool.query(`
        WITH pres AS (
          SELECT
            CASE
              WHEN pi2.nome ILIKE '%LAB%' THEN 'LAB. Vozes do Futuro'
              WHEN pi2.nome ILIKE '%PRESENCIAL%' THEN 'Cursos Presenciais'
              WHEN pi2.nome ILIKE '%EAD%' THEN 'Cursos EAD CGD'
              ELSE COALESCE(pi2.nome, 'Outros')
            END AS programa,
            pr.presente,
            pr.teve_alimentacao,
            pr.justificativa,
            pr.turma_id,
            pr.data,
            ti.horario_entrada::text AS horario_entrada,
            ti.horario_saida::text AS horario_saida,
            ti.horario::text AS horario
          FROM presencas_inclusao pr
          JOIN turmas_inclusao ti ON ti.id = pr.turma_id
          LEFT JOIN programas_inclusao pi2 ON pi2.id = ti.programa_id
          WHERE EXTRACT(YEAR FROM pr.data) = $1
            AND EXTRACT(MONTH FROM pr.data) BETWEEN $2 AND $3
        ),
        metricas AS (
          SELECT
            programa,
            COUNT(CASE WHEN presente = true THEN 1 END)::int AS atendimentos,
            COUNT(CASE WHEN presente = true AND teve_alimentacao = true THEN 1 END)::int AS alimentacao,
            COUNT(CASE WHEN presente = true THEN 1 END)::numeric AS presencas_numerador,
            COUNT(CASE WHEN NOT (presente = false AND justificativa IS NOT NULL AND justificativa != '' AND justificativa != 'Sem justificativa') THEN 1 END)::numeric AS presencas_denominador
          FROM pres
          GROUP BY programa
        ),
        horas AS (
          SELECT
            programa,
            SUM(
              CASE
                WHEN presente = true THEN
                  CASE
                    WHEN horario_entrada IS NOT NULL AND horario_saida IS NOT NULL THEN
                      GREATEST(
                        (
                          (split_part(horario_saida, ':', 1)::int * 60 + split_part(horario_saida, ':', 2)::int) -
                          (split_part(horario_entrada, ':', 1)::int * 60 + split_part(horario_entrada, ':', 2)::int)
                        ) / 60.0, 0
                      )
                    ELSE 0
                  END
                ELSE 0
              END
            ) AS hora_aula
          FROM pres
          GROUP BY programa
        )
        SELECT
          m.programa,
          m.atendimentos,
          m.alimentacao,
          ROUND(COALESCE(h.hora_aula, 0))::int AS hora_aula,
          ROUND(
            CASE WHEN m.presencas_denominador > 0
              THEN (m.presencas_numerador / m.presencas_denominador) * 100
              ELSE 0
            END
          )::int AS frequencia
        FROM metricas m
        LEFT JOIN horas h ON h.programa = m.programa
        ORDER BY m.atendimentos DESC
      `, [ano, mesInicio, mesFim]);
      res.json({
        success: true,
        ano,
        mes: mes || null,
        trimestre: trimestre || null,
        programas: result.rows.map((r) => ({
          nome: r.programa,
          atendimentos: Number(r.atendimentos || 0),
          alimentacao: Number(r.alimentacao || 0),
          horaAula: Number(r.hora_aula || 0),
          frequencia: Number(r.frequencia || 0)
        }))
      });
    } catch (error) {
      console.error("[INCLUSAO BREAKDOWN] Erro:", error);
      res.status(500).json({ success: false, error: "Erro ao buscar breakdown por programa" });
    }
  });
  app2.get("/api/psicossocial/indicadores", async (req, res) => {
    try {
      const ano = parseInt(req.query.ano) || (/* @__PURE__ */ new Date()).getFullYear();
      const mes = req.query.mes ? parseInt(req.query.mes) : null;
      console.log(`[PSICO INDICADORES] Buscando indicadores ano=${ano}, mes=${mes || "anual"}...`);
      const [registrosResult, atividadesResult] = await Promise.all([
        pool.query(`
          SELECT tipo, EXTRACT(MONTH FROM data::date) as mes, COUNT(*) as total
          FROM psico_registros_confidenciais
          WHERE EXTRACT(YEAR FROM data::date) = $1 AND status = 'ativo'
          GROUP BY tipo, EXTRACT(MONTH FROM data::date)
          ORDER BY tipo, mes
        `, [ano]),
        pool.query(`
          SELECT tipo, EXTRACT(MONTH FROM data) as mes, COUNT(*) as total
          FROM atividades_monitor
          WHERE contexto = 'psicossocial'
            AND EXTRACT(YEAR FROM data) = $1
            AND status != 'cancelada'
          GROUP BY tipo, EXTRACT(MONTH FROM data)
          ORDER BY tipo, mes
        `, [ano])
      ]);
      const registrosLabels = {
        "atendimento_individual": "Atendimento Individual",
        "visita_domiciliar": "Visita Domiciliar",
        "atendimento_coletivo": "Atendimento Coletivo",
        "espaco_o_grito": "Espa\xE7o O Grito",
        "acoes_saude": "A\xE7\xF5es para a Sa\xFAde",
        "encaminhamento": "Encaminhamento",
        "situacao_risco": "Situa\xE7\xE3o de Risco",
        "contato_familiar": "Contato Familiar",
        "relato_espontaneo": "Relato Espont\xE2neo",
        "observacao_comportamental": "Observa\xE7\xE3o Comportamental",
        "outro": "Outro"
      };
      const atividadesLabels = {
        "roda_de_conversa": "Roda de Conversa",
        "atendimento_grupo": "Atendimento em Grupo",
        "oficina": "Oficina",
        "acao_socioemocional": "A\xE7\xE3o Socioemocional",
        "palestra": "Palestra",
        "visita_domiciliar": "Visita Domiciliar",
        "encaminhamento": "Encaminhamento",
        "reforco": "Refor\xE7o",
        "recreativa": "Recreativa",
        "outro": "Outro"
      };
      const processRows = (rows, labels) => {
        const data = {};
        for (const [key2, label] of Object.entries(labels)) {
          data[key2] = { label, total: 0, mensal: Array(12).fill(0) };
        }
        for (const row of rows) {
          const tipo = row.tipo;
          const mesIdx = parseInt(row.mes) - 1;
          const count = parseInt(row.total);
          if (!data[tipo]) {
            data[tipo] = { label: labels[tipo] || tipo, total: 0, mensal: Array(12).fill(0) };
          }
          data[tipo].mensal[mesIdx] += count;
          data[tipo].total += count;
        }
        return data;
      };
      const registros = processRows(registrosResult.rows, registrosLabels);
      const atividades = processRows(atividadesResult.rows, atividadesLabels);
      const applyMesFilter = (data) => {
        let total = 0;
        const filtrado = {};
        for (const [key2, d] of Object.entries(data)) {
          if (mes !== null) {
            const valorMes = d.mensal[mes - 1] || 0;
            filtrado[key2] = { ...d, total: valorMes };
            total += valorMes;
          } else {
            filtrado[key2] = d;
            total += d.total;
          }
        }
        return { filtrado, total };
      };
      const regFiltrado = applyMesFilter(registros);
      const ativFiltrado = applyMesFilter(atividades);
      const totalGeral = regFiltrado.total + ativFiltrado.total;
      console.log(`[PSICO INDICADORES] Registros: ${regFiltrado.total}, Atividades: ${ativFiltrado.total}, Total: ${totalGeral}`);
      res.json({
        ano,
        mes: mes || null,
        totalGeral,
        registrosConfidenciais: { total: regFiltrado.total, indicadores: regFiltrado.filtrado },
        relatosAtividades: { total: ativFiltrado.total, indicadores: ativFiltrado.filtrado }
      });
    } catch (error) {
      console.error("[PSICO INDICADORES] Erro:", error);
      res.status(500).json({ error: "Erro ao buscar indicadores psicossociais" });
    }
  });
