  function gerarSiglasEvento(titulo) {
    const stopWords = /* @__PURE__ */ new Set(["de", "do", "da", "dos", "das", "a", "o", "e", "em", "no", "na", "nos", "nas", "um", "uma", "por", "para", "com", "ao", "aos"]);
    const words = titulo.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-zA-Z0-9\s]/g, "").split(/\s+/).filter(Boolean);
    const siglas = words.filter((w) => w.length > 1 && !stopWords.has(w.toLowerCase())).map((w) => w[0].toUpperCase()).join("");
    return siglas.slice(0, 5) || "EVT";
  }
  async function gerarIngressosParaEvento(eventoId, quantidade2, eventoTitulo) {
    const { rows: [cnt] } = await pool.query(
      "SELECT COUNT(*) as total FROM ingressos_portal WHERE evento_id=$1",
      [eventoId]
    );
    const startSeq = parseInt(cnt.total) + 1;
    const titulo = eventoTitulo || "EVT";
    const siglas = gerarSiglasEvento(titulo);
    const eventoIdStr = String(eventoId).padStart(3, "0");
    for (let i = 0; i < quantidade2; i++) {
      const seq = startSeq + i;
      const seqStr = String(seq).padStart(3, "0");
      const codigo = `GRT${seqStr}${siglas}${eventoIdStr}`;
      await pool.query(
        "INSERT INTO ingressos_portal (evento_id, codigo, status) VALUES ($1, $2, $3)",
        [eventoId, codigo, "disponivel"]
      );
    }
  }
