  app2.get("/api/eventos-grito/:id/estatisticas", requireEventosAdmin, async (req, res) => {
    try {
      const eventoId = req.params.id;
      const { rows: [evento] } = await pool.query(`SELECT * FROM eventos_grito WHERE id=$1`, [eventoId]);
      if (!evento) return res.status(404).json({ error: "Evento n\xE3o encontrado" });
      const { rows: ing } = await pool.query(`
        SELECT i.id, i.status, i.codigo
        FROM ingressos_portal i
        WHERE i.evento_id = $1
      `, [eventoId]);
      const disponibilizados = evento.capacidade || 0;
      const vendidos = ing.filter((i) => ["resgatado", "usado"].includes(i.status)).length;
      const escaneados = ing.filter((i) => i.status === "usado").length;
      const ticketMedio = vendidos > 0 ? Math.round(evento.preco || 0) : 0;
      const { rows: demoRows } = await pool.query(`
        SELECT
          CASE WHEN ip.para_terceiro THEN ip.beneficiario_genero ELSE up.genero END as genero,
          CASE WHEN ip.para_terceiro THEN ip.beneficiario_cidade ELSE up.cidade END as cidade,
          CASE WHEN ip.para_terceiro THEN ip.beneficiario_nascimento ELSE up.data_nascimento END as nascimento
        FROM ingressos_portal ip
        LEFT JOIN usuarios_portal up ON up.id = ip.usuario_portal_id
        WHERE ip.evento_id = $1 AND ip.status = 'usado'
      `, [eventoId]);
      const generoCounts = {};
      for (const r of demoRows) {
        const g = r.genero || "n\xE3o_informado";
        generoCounts[g] = (generoCounts[g] || 0) + 1;
      }
      const generoLabels = {
        masculino: "Masculino",
        feminino: "Feminino",
        nao_binario: "N\xE3o bin\xE1rio",
        outro: "Outro",
        prefiro_nao_informar: "Prefiro n\xE3o informar",
        n\u00E3o_informado: "N\xE3o informado"
      };
      const genero = Object.entries(generoCounts).map(([key2, count]) => ({
        label: generoLabels[key2] || key2,
        value: count
      }));
      const cidadeCounts = {};
      for (const r of demoRows) {
        if (r.cidade) {
          cidadeCounts[r.cidade] = (cidadeCounts[r.cidade] || 0) + 1;
        }
      }
      const cidades = Object.entries(cidadeCounts).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([label, value]) => ({ label, value }));
      const faixas = { "Menor de 18": 0, "18-25": 0, "26-35": 0, "36-50": 0, "50+": 0, "N\xE3o informado": 0 };
      for (const r of demoRows) {
        if (!r.nascimento) {
          faixas["N\xE3o informado"]++;
          continue;
        }
        const age = Math.floor((Date.now() - new Date(r.nascimento).getTime()) / (365.25 * 24 * 3600 * 1e3));
        if (age < 18) faixas["Menor de 18"]++;
        else if (age <= 25) faixas["18-25"]++;
        else if (age <= 35) faixas["26-35"]++;
        else if (age <= 50) faixas["36-50"]++;
        else faixas["50+"]++;
      }
      const faixaEtaria = Object.entries(faixas).filter(([, v]) => v > 0).map(([label, value]) => ({ label, value }));
      res.json({
        evento,
        ingressos: { disponibilizados, vendidos, escaneados, ticketMedio },
        demograficos: { genero, faixaEtaria, cidades, total: demoRows.length }
      });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });
