  app2.get("/api/marketing-metricas", async (req, res) => {
    try {
      const ano = parseInt(req.query.ano) || (/* @__PURE__ */ new Date()).getFullYear();
      const categoria = (req.query.categoria || "todos").toLowerCase();
      const trimestreRaw = req.query.trimestre || "todos";
      const trimestre = trimestreRaw.toLowerCase() === "todos" ? "todos" : trimestreRaw;
      const params = [ano];
      let query = `
        SELECT id, ano, nome, categoria, unidade, realizado, meta, ordem, trimestre, inversa, updated_at
        FROM marketing_metricas_custom
        WHERE ano = $1
      `;
      if (categoria !== "todos") {
        params.push(categoria);
        query += ` AND categoria = $${params.length} `;
      }
      if (trimestre !== "todos") {
        params.push(trimestre);
        query += ` AND trimestre = $${params.length} `;
      }
      query += ` ORDER BY trimestre ASC NULLS LAST, ordem ASC, nome ASC `;
      const result = await pool.query(query, params);
      const metricas = result.rows.map((r) => {
        const realizado = Number(r.realizado || 0);
        const meta = Number(r.meta || 0);
        const progresso = meta > 0 ? Number((realizado / meta * 100).toFixed(1)) : 0;
        return {
          id: r.id,
          ano: r.ano,
          nome: r.nome,
          categoria: r.categoria,
          unidade: r.unidade,
          trimestre: r.trimestre || "todos",
          inversa: Boolean(r.inversa),
          realizado,
          meta,
          progresso,
          updatedAt: r.updated_at
        };
      });
      return res.json({ ano, categoria, trimestre, metricas });
    } catch (e) {
      console.error("[MARKETING METRICAS GET]", e.message);
      return res.status(500).json({ error: e.message });
    }
  });
