  app2.get("/api/proxy/image", async (req, res) => {
    try {
      const rawPath = req.query.path || req.query.url;
      if (!rawPath) return res.status(400).json({ error: "Path obrigat\xF3rio" });
      res.set("Cache-Control", "public, max-age=3600");
      res.set("Access-Control-Allow-Origin", "*");
      if (rawPath.startsWith("http://") || rawPath.startsWith("https://")) {
        try {
          const fetchRes = await fetch(rawPath);
          if (!fetchRes.ok) throw new Error("not ok");
          const buffer = await fetchRes.arrayBuffer();
          const contentType2 = fetchRes.headers.get("content-type") || "image/jpeg";
          res.set("Content-Type", contentType2);
          return res.send(Buffer.from(buffer));
        } catch {
          return res.status(404).send("Imagem n\xE3o encontrada");
        }
      }
      if (!bucket) return res.status(503).json({ error: "GCS n\xE3o dispon\xEDvel" });
      const cleanPath = normalizeObjectKey(rawPath);
      const file = bucket.file(cleanPath);
      const [exists] = await file.exists();
      if (!exists) return res.status(404).send("Imagem n\xE3o encontrada no GCS");
      const [meta] = await file.getMetadata();
      const contentType = meta.contentType || "image/jpeg";
      res.set("Content-Type", contentType);
      file.createReadStream().on("error", () => res.status(500).send("Erro ao ler imagem")).pipe(res);
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });
