  app2.post("/api/tablet-chamada/login", passwordLoginLimiter, async (req, res) => {
    const LOGIN_ERRO_GENERICO = "Usu\xE1rio ou senha incorretos";
    const DUMMY_BCRYPT_HASH = "$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZ5L17lhWy";
    try {
      const username = String(req.body?.username || "").trim().toLowerCase();
      const senha = String(req.body?.senha || "");
      if (!username || !senha) {
        return res.status(400).json({ error: "Usu\xE1rio e senha obrigat\xF3rios" });
      }
      if (username.length > 64 || senha.length > 128) {
        return res.status(400).json({ error: LOGIN_ERRO_GENERICO });
      }
      const { rows } = await pool.query(
        `SELECT * FROM tablet_chamada_usuarios WHERE username = $1 AND ativo = true LIMIT 1`,
        [username]
      );
      const bcryptMod = await import("bcryptjs");
      const bcrypt3 = bcryptMod.default || bcryptMod;
      const hashToCompare = rows.length ? rows[0].senha_hash : DUMMY_BCRYPT_HASH;
      const ok = await bcrypt3.compare(senha, hashToCompare);
      if (!rows.length || !ok) {
        console.warn(`[tablet-chamada] Login falhou para usu\xE1rio: ${username || "(vazio)"}`);
        return res.status(401).json({ error: LOGIN_ERRO_GENERICO });
      }
      const usuario = rows[0];
      const vertente = usuario.vertente === "inclusao" ? "inclusao" : "pec";
      await regenerateExpressSession(req);
      await establishTabletChamadaSession(req, {
        id: usuario.id,
        nome: usuario.nome,
        username: usuario.username,
        vertente
      });
      return res.json({
        success: true,
        usuario: { id: usuario.id, nome: usuario.nome, username: usuario.username, vertente }
      });
    } catch (e) {
      console.error("Tablet chamada login error:", e);
      return res.status(500).json({ error: "Erro interno" });
    }
  });
