  app2.get("/api/mapeamentos/stats", requireAuth, async (req, res) => {
    try {
      const ano = req.query.ano ? Number(req.query.ano) : null;
      const mes = req.query.mes ? Number(req.query.mes) : null;
      const trimestre = req.query.trimestre ? Number(req.query.trimestre) : null;
      const mapMesInicio = req.query.mesInicio ? Number(req.query.mesInicio) : null;
      const mapMesFim = req.query.mesFim ? Number(req.query.mesFim) : null;
      const mapRangeValid = !trimestre && mapMesInicio !== null && mapMesFim !== null && mapMesInicio >= 1 && mapMesInicio <= 12 && mapMesFim >= 1 && mapMesFim <= 12 && mapMesInicio <= mapMesFim;
      const monitorId = req.query.monitorId ? Number(req.query.monitorId) : null;
      let sql6 = "SELECT COALESCE(SUM(casas_mapeadas),0) AS total FROM mapeamentos_territorio WHERE 1=1";
      const params = [];
      if (ano) {
        params.push(ano);
        sql6 += ` AND EXTRACT(YEAR FROM data) = $${params.length}`;
      }
      if (trimestre && trimestre >= 1 && trimestre <= 4) {
        const mesInicio = (trimestre - 1) * 3 + 1;
        const mesFim = trimestre * 3;
        params.push(mesInicio);
        sql6 += ` AND EXTRACT(MONTH FROM data) >= $${params.length}`;
        params.push(mesFim);
        sql6 += ` AND EXTRACT(MONTH FROM data) <= $${params.length}`;
      } else if (mapRangeValid) {
        params.push(mapMesInicio);
        sql6 += ` AND EXTRACT(MONTH FROM data) >= $${params.length}`;
        params.push(mapMesFim);
        sql6 += ` AND EXTRACT(MONTH FROM data) <= $${params.length}`;
      } else if (mes && mes > 0) {
        params.push(mes);
        sql6 += ` AND EXTRACT(MONTH FROM data) = $${params.length}`;
      }
      if (monitorId) {
        params.push(monitorId);
        sql6 += ` AND monitor_id = $${params.length}`;
      }
      const r = await pool.query(sql6, params);
      res.json({ total: Number(r.rows[0]?.total ?? 0) });
    } catch (e) {
      console.error("GET /api/mapeamentos/stats:", e);
      res.status(500).json({ error: "Erro interno" });
    }
  });
