function conditionalJsonParser() {
  return (req, res, next) => {
    if (req.originalUrl.startsWith("/api/webhook/stripe") || req.originalUrl.startsWith("/api/stripe/webhook") || req.originalUrl.startsWith("/api/typeform/webhook")) {
      return next();
    }
    return express4.json({ limit: bodyLimitForUrl(req.originalUrl) })(req, res, next);
  };
}
function conditionalUrlencodedParser() {
  return (req, res, next) => {
    if (req.originalUrl.startsWith("/api/webhook/stripe") || req.originalUrl.startsWith("/api/stripe/webhook") || req.originalUrl.startsWith("/api/typeform/webhook")) {
      return next();
    }
    return express4.urlencoded({
      extended: false,
      limit: bodyLimitForUrl(req.originalUrl)
    })(req, res, next);
  };
}

